from taf.gnb.oam.megazone_client import megazone_client

get_active_fault_number_path = "taf.gnb.oam.megazone_client.alarms_endpoint.AlarmsEndpoint.get_active_faults_number"
get_historic_faults_number_path = "taf.gnb.oam.megazone_client.alarms_endpoint.AlarmsEndpoint.get_historic_faults_number"

try:
    import unittest2 as unittest
except ImportError:
    import unittest

try:
    from mock import Mock, patch
except ImportError:
    from unittest.mock import Mock, patch


class TestBTSWithoutFaults(unittest.TestCase):
    def setUp(self):
        self.cor = megazone_client()
        self.cor.session_handler = Mock()
        self.cor.session_store.add(Mock())

    @patch(get_active_fault_number_path, return_value=0)
    def test_check_active_faults_shouldPass(self, m_active):
        self.cor.check_active_faults()

    @patch(get_historic_faults_number_path, return_value=0)
    def test_check_historic_faults_shouldPass(self, m_historic):
        self.cor.check_historic_faults()

    @patch(get_active_fault_number_path, return_value=0)
    @patch(get_historic_faults_number_path, return_value=0)
    def test_check_all_faults_shouldPass(self, m_active, m_historic):
        self.cor.check_all_faults()
